#!/usr/bin/env python3
# Generated by nova via A2A Mesh delegation
"""
Delegált feladatok pre-fetching — a cél-node előre betölti a szükséges
skill-eket és kontextust még az átvétel előtt.

Ez a modul implementálja a pre-fetching mechanizmust:
- Amikor egy feladat delegálásra kerül, a forrás-node küld egy PREFETCH
  üzenetet a cél-node-nak a skill-ek és kontextus azonosítóival.
- A cél-node elkezdi betölteni a skill-eket és kontextust a háttérben.
- Amikor a tényleges feladat megérkezik, a cél-node már rendelkezik
  minden szükséges erőforrással, így az átvétel és végrehajtás azonnal
  megtörténhet.
- Ha a prefetch még fut, a cél-node vár rá (de legfeljebb egy timeout-ig).
"""

import time
import json
import hashlib
import threading
import logging
from dataclasses import dataclass, field
from enum import Enum
from typing import Dict, List, Optional, Set, Callable, Any
from concurrent.futures import ThreadPoolExecutor, Future

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(name)s: %(message)s"
)
logger = logging.getLogger("a2a_mesh.prefetch")


# ---------------------------------------------------------------------------
# Data structures
# ---------------------------------------------------------------------------

class PrefetchState(Enum):
    """A prefetch kérés állapota a cél-node-on."""
    IDLE = "idle"
    LOADING = "loading"
    READY = "ready"
    FAILED = "failed"
    EXPIRED = "expired"


@dataclass
class SkillDescriptor:
    """Egy skill leírása, amit a cél-node-nak be kell töltenie."""
    skill_id: str
    version: str = "latest"
    source: str = "local"  # local | remote | registry
    checksum: Optional[str] = None

    def key(self) -> str:
        return f"{self.skill_id}@{self.version}"


@dataclass
class ContextDescriptor:
    """Egy kontextus-elem leírása, amit a cél-node-nak be kell töltenie."""
    context_id: str
    context_type: str = "generic"  # generic | file | url | memory
    size_hint: int = 0  # becsült méret byte-ban
    metadata: Dict[str, Any] = field(default_factory=dict)

    def key(self) -> str:
        return self.context_id


@dataclass
class PrefetchRequest:
    """
    A PREFETCH üzenet, amit a forrás-node küld a cél-node-nak
    még a tényleges feladat-delegálás előtt.
    """
    request_id: str
    task_id: str          # a hamarosan érkező feladat azonosítója
    source_node: str      # küldő node azonosítója
    target_node: str      # cél node azonosítója
    skills: List[SkillDescriptor] = field(default_factory=list)
    contexts: List[ContextDescriptor] = field(default_factory=list)
    ttl_seconds: float = 30.0  # meddig tartson a prefetch cache
    created_at: float = field(default_factory=time.time)

    def fingerprint(self) -> str:
        """Egyedi hash a prefetch tartalmából — deduplikációhoz."""
        payload = json.dumps({
            "skills": sorted(s.key() for s in self.skills),
            "contexts": sorted(c.key() for c in self.contexts),
        }, sort_keys=True)
        return hashlib.sha256(payload.encode()).hexdigest()[:16]


@dataclass
class PrefetchResult:
    """A prefetch végrehajtás eredménye."""
    request_id: str
    state: PrefetchState
    loaded_skills: List[str] = field(default_factory=list)
    loaded_contexts: List[str] = field(default_factory=list)
    errors: List[str] = field(default_factory=list)
    duration_ms: float = 0.0


# ---------------------------------------------------------------------------
# Skill Registry — skill-ek betöltése és cache-elése
# ---------------------------------------------------------------------------

class SkillRegistry:
    """
    Skill-ek betöltése és cache-elése a cél-node-on.
    A betöltés szimulált: valós rendszerben ez lehet plugin-import,
    container-pull, model-download, stb.
    """

    def __init__(self, loader_fn: Optional[Callable[[str], Any]] = None):
        self._cache: Dict[str, Any] = {}
        self._lock = threading.RLock()
        self._loader_fn = loader_fn or self._default_loader
        self._load_times: Dict[str, float] = {}

    def _default_loader(self, skill_key: str) -> Any:
        """Szimulált skill betöltés — valós rendszerben felülírható."""
        # Szimuláljuk a betöltési időt skill mérete alapján
        time.sleep(0.05 + (hash(skill_key) % 100) / 1000.0)
        return {"skill": skill_key, "loaded_at": time.time()}

    def is_loaded(self, skill_key: str) -> bool:
        with self._lock:
            return skill_key in self._cache

    def load(self, skill: SkillDescriptor) -> Any:
        key = skill.key()
        with self._lock:
            if key in self._cache:
                logger.debug(f"Skill cache hit: {key}")
                return self._cache[key]

        logger.info(f"Loading skill: {key} (source={skill.source})")
        start = time.time()
        try:
            obj = self._loader_fn(key)
        except Exception as e:
            logger.error(f"Failed to load skill {key}: {e}")
            raise

        with self._lock:
            self._cache[key] = obj
            self._load_times[key] = time.time() - start

        logger.info(f"Skill loaded: {key} in {self._load_times[key]*1000:.1f}ms")
        return obj

    def load_many(self, skills: List[SkillDescriptor]) -> Dict[str, Any]:
        results: Dict[str, Any] = {}
        errors: List[str] = []

        def _load_one(s: SkillDescriptor):
            try:
                results[s.key()] = self.load(s)
            except Exception as e:
                errors.append(f"{s.key()}: {e}")

        with ThreadPoolExecutor(max_workers=4) as pool:
            list(pool.map(_load_one, skills))

        if errors:
            logger.warning(f"Skill load errors: {errors}")
        return results

    def evict(self, skill_key: str):
        with self._lock:
            self._cache.pop(skill_key, None)
            self._load_times.pop(skill_key, None)

    def stats(self) -> Dict[str, Any]:
        with self._lock:
            return {
                "cached_skills": len(self._cache),
                "load_times_ms": {
                    k: v * 1000 for k, v in self._load_times.items()
                },
            }


# ---------------------------------------------------------------------------
# Context Cache — kontextus adatok betöltése és cache-elése
# ---------------------------------------------------------------------------

class ContextCache:
    """
    Kontextus adatok betöltése és cache-elése a cél-node-on.
    Lehet fájl, URL, memória-szegmens, stb.
    """

    def __init__(self, loader_fn: Optional[Callable[[str, str], Any]] = None):
        self._cache: Dict[str, Any] = {}
        self._lock = threading.RLock()
        self._loader_fn = loader_fn or self._default_loader
        self._load_times: Dict[str, float] = {}

    def _default_loader(self, context_id: str, context_type: str) -> Any:
        """Szimulált kontextus betöltés."""
        # Különböző típusok különböző idővel
        base_delay = {
            "file": 0.08,
            "url": 0.15,
            "memory": 0.02,
            "generic": 0.05,
        }.get(context_type, 0.05)
        time.sleep(base_delay + (hash(context_id) % 50) / 1000.0)
        return {
            "context_id": context_id,
            "type": context_type,
            "data": f"context_data_for_{context_id}",
            "loaded_at": time.time(),
        }

    def is_loaded(self, context_key: str) -> bool:
        with self._lock:
            return context_key in self._cache

    def load(self, ctx: ContextDescriptor) -> Any:
        key = ctx.key()
        with self._lock:
            if key in self._cache:
                logger.debug(f"Context cache hit: {key}")
                return self._cache[key]

        logger.info(f"Loading context: {key} (type={ctx.context_type})")
        start = time.time()
        try:
            obj = self._loader_fn(key, ctx.context_type)
        except Exception as e:
            logger.error(f"Failed to load context {key}: {e}")
            raise

        with self._lock:
            self._cache[key] = obj
            self._load_times[key] = time.time() - start

        logger.info(f"Context loaded: {key} in {self._load_times[key]*1000:.1f}ms")
        return obj

    def load_many(self, contexts: List[ContextDescriptor]) -> Dict[str, Any]:
        results: Dict[str, Any] = {}
        errors: List[str] = []

        def _load_one(c: ContextDescriptor):
            try:
                results[c.key()] = self.load(c)
            except Exception as e:
                errors.append(f"{c.key()}: {e}")

        with ThreadPoolExecutor(max_workers=4) as pool:
            list(pool.map(_load_one, contexts))

        if errors:
            logger.warning(f"Context load errors: {errors}")
        return results

    def evict(self, context_key: str):
        with self._lock:
            self._cache.pop(context_key, None)
            self._load_times.pop(context_key, None)

    def stats(self) -> Dict[str, Any]:
        with self._lock:
            return {
                "cached_contexts": len(self._cache),
                "load_times_ms": {
                    k: v * 1000 for k, v in self._load_times.items()
                },
            }


# ---------------------------------------------------------------------------
# Prefetch Manager — a cél-node-on fut, kezeli a prefetch kéréseket
# ---------------------------------------------------------------------------

class PrefetchManager:
    """
    A cél-node prefetch managere. Amikor egy PREFETCH kérés érkezik,
    elindítja a skill-ek és kontextusok betöltését a háttérben.
    Amikor a tényleges feladat megérkezik, a ensure_ready() metódus
    ellenőrzi, hogy minden kész-e (vár ha kell).
    """

    def __init__(
        self,
        node_id: str,
        skill_registry: Optional[SkillRegistry] = None,
        context_cache: Optional[ContextCache] = None,
        default_ttl: float = 30.0,
    ):
        self.node_id = node_id
        self.skill_registry = skill_registry or SkillRegistry()
        self.context_cache = context_cache or ContextCache()
        self.default_ttl = default_ttl

        self._prefetches: Dict[str, Dict[str, Any]] = {}  # request_id -> info
        self._fingerprints: Dict[str, str] = {}  # fingerprint -> request_id (dedup)
        self._lock = threading.RLock()
        self._executor = ThreadPoolExecutor(max_workers=4, thread_name_prefix="prefetch")

        # TTL cleanup thread
        self._cleanup_stop = threading.Event()
        self._cleanup_thread = threading.Thread(
            target=self._ttl_cleanup_loop, daemon=True, name="prefetch-ttl"
        )
        self._cleanup_thread.start()

    def handle_prefetch(self, request: PrefetchRequest) -> PrefetchResult:
        """
        Feldolgoz egy bejövő PREFETCH kérést.
        Azonnal visszatér — a betöltés a háttérben történik.
        """
        logger.info(
            f"[{self.node_id}] PREFETCH received: {request.request_id} "
            f"(task={request.task_id}, skills={len(request.skills)}, "
            f"contexts={len(request.contexts)})"
        )

        # Deduplikáció: ha már van azonos fingerprintű prefetch, újrahasználjuk
        fp = request.fingerprint()
        with self._lock:
            if fp in self._fingerprints:
                existing_id = self._fingerprints[fp]
                if existing_id in self._prefetches:
                    existing = self._prefetches[existing_id]
                    if existing["state"] in (PrefetchState.READY, PrefetchState.LOADING):
                        logger.info(
                            f"[{self.node_id}] Prefetch dedup: "
                            f"reusing {existing_id} for {request.request_id}"
                        )
                        # Linkeljük az új request_id-t a meglévőhöz
                        self._prefetches[request.request_id] = existing
                        return PrefetchResult(
                            request_id=request.request_id,
                            state=existing["state"],
                            loaded_skills=existing.get("loaded_skills", []),
                            loaded_contexts=existing.get("loaded_contexts", []),
                        )

        # Új prefetch indítása
        start_time = time.time()
        info: Dict[str, Any] = {
            "request_id": request.request_id,
            "task_id": request.task_id,
            "fingerprint": fp,
            "state": PrefetchState.LOADING,
            "skills": [s.key() for s in request.skills],
            "contexts": [c.key() for c in request.contexts],
            "loaded_skills": [],
            "loaded_contexts": [],
            "errors": [],
            "created_at": time.time(),
            "expires_at": time.time() + request.ttl_seconds,
            "future": None,
        }

        with self._lock:
            self._prefetches[request.request_id] = info
            self._fingerprints[fp] = request.request_id

        # Háttérben betöltés
        future = self._executor.submit(
            self._do_prefetch, request, info, start_time
        )
        with self._lock:
            info["future"] = future

        return PrefetchResult(
            request_id=request.request_id,
            state=PrefetchState.LOADING,
        )

    def _do_prefetch(
        self,
        request: PrefetchRequest,
        info: Dict[str, Any],
        start_time: float,
    ):
        """A tényleges betöltés — háttérszálon fut."""
        loaded_skills: List[str] = []
        loaded_contexts: List[str] = []
        errors: List[str] = []

        # Skill-ek betöltése
        if request.skills:
            try:
                self.skill_registry.load_many(request.skills)
                loaded_skills = [s.key() for s in request.skills]
            except Exception as e:
                errors.append(f"skills: {e}")

        # Kontextusok betöltése
        if request.contexts:
            try:
                self.context_cache.load_many(request.contexts)
                loaded_contexts = [c.key() for c in request.contexts]
            except Exception as e:
                errors.append(f"contexts: {e}")

        duration_ms = (time.time() - start_time) * 1000

        with self._lock:
            info["loaded_skills"] = loaded_skills
            info["loaded_contexts"] = loaded_contexts
            info["errors"] = errors
            info["state"] = PrefetchState.FAILED if errors else PrefetchState.READY
            info["duration_ms"] = duration_ms

        state = info["state"]
        logger.info(
            f"[{self.node_id}] PREFETCH complete: {request.request_id} "
            f"state={state.value} duration={duration_ms:.1f}ms "
            f"skills={len(loaded_skills)} contexts={len(loaded_contexts)}"
        )

    def ensure_ready(
        self,
        task_id: str,
        skills: List[SkillDescriptor],
        contexts: List[ContextDescriptor],
        timeout: float = 10.0,
    ) -> PrefetchResult:
        """
        Ellenőrzi, hogy a megadott task-hoz szükséges erőforrások készen állnak.
        Ha volt prefetch, vár rá (legfeljebb timeout-ig).
        Ha nem volt prefetch, betölti azonnal (fallback).
        """
        # Keresünk egyező prefetch-et task_id alapján
        matching_request_id: Optional[str] = None
        with self._lock:
            for rid, info in self._prefetches.items():
                if info.get("task_id") == task_id:
                    matching_request_id = rid
                    break

        if matching_request_id:
            info = self._prefetches[matching_request_id]
            future: Optional[Future] = info.get("future")

            if future and not future.done():
                logger.info(
                    f"[{self.node_id}] Waiting for prefetch to complete "
                    f"(task={task_id}, timeout={timeout}s)"
                )
                try:
                    future.result(timeout=timeout)
                except Exception as e:
                    logger.warning(
                        f"[{self.node_id}] Prefetch wait failed/timed out: {e}"
                    )

            with self._lock:
                state = info.get("state", PrefetchState.IDLE)
                loaded_s = info.get("loaded_skills", [])
                loaded_c = info.get("loaded_contexts", [])
                errors = info.get("errors", [])
                duration = info.get("duration_ms", 0.0)

            if state == PrefetchState.READY:
                logger.info(f"[{self.node_id}] Prefetch HIT for task={task_id}")
                return PrefetchResult(
                    request_id=matching_request_id,
                    state=PrefetchState.READY,
                    loaded_skills=loaded_s,
                    loaded_contexts=loaded_c,
                    duration_ms=duration,
                )
            else:
                logger.warning(
                    f"[{self.node_id}] Prefetch MISS/FAILED for task={task_id}, "
                    f"falling back to direct load"
                )

        # Fallback: közvetlen betöltés (nem volt prefetch vagy sikertelen)
        logger.info(f"[{self.node_id}] Direct load for task={task_id}")
        start = time.time()
        loaded_s: List[str] = []
        loaded_c: List[str] = []
        errors: List[str] = []

        try:
            self.skill_registry.load_many(skills)
            loaded_s = [s.key() for s in skills]
        except Exception as e:
            errors.append(f"skills: {e}")

        try:
            self.context_cache.load_many(contexts)
            loaded_c = [c.key() for c in contexts]
        except Exception as e:
            errors.append(f"contexts: {e}")

        duration_ms = (time.time() - start) * 1000
        state = PrefetchState.FAILED if errors else PrefetchState.READY

        return PrefetchResult(
            request_id="direct",
            state=state,
            loaded_skills=loaded_s,
            loaded_contexts=loaded_c,
            errors=errors,
            duration_ms=duration_ms,
        )

    def get_prefetch_state(self, request_id: str) -> Optional[PrefetchState]:
        with self._lock:
            info = self._prefetches.get(request_id)
            return info["state"] if info else None

    def list_prefetches(self) -> List[Dict[str, Any]]:
        with self._lock:
            return [
                {
                    "request_id": info["request_id"],
                    "task_id": info.get("task_id"),
                    "state": info["state"].value,
                    "skills": info.get("skills", []),
                    "contexts": info.get("contexts", []),
                    "expires_at": info.get("expires_at"),
                }
                for info in self._prefetches.values()
            ]

    def _ttl_cleanup_loop(self):
        """Háttérszálon törli a lejárt prefetch bejegyzéseket."""
        while not self._cleanup_stop.wait(5.0):
            now = time.time()
            to_remove: List[str] = []
            with self._lock:
                for rid, info in self._prefetches.items():
                    expires = info.get("expires_at", 0)
                    if expires and expires < now:
                        info["state"] = PrefetchState.EXPIRED
                        to_remove.append(rid)

                for rid in to_remove:
                    info = self._prefetches.pop(rid, None)
                    if info:
                        fp = info.get("fingerprint")
                        if fp and self._fingerprints.get(fp) == rid:
                            del self._fingerprints[fp]
                        logger.debug(
                            f"[{self.node_id}] Expired prefetch: {rid}"
                        )

    def shutdown(self):
        self._cleanup_stop.set()
        self._executor.shutdown(wait=True, cancel_futures=True)
        logger.info(f"[{self.node_id}] PrefetchManager shut down")


# ---------------------------------------------------------------------------
# Delegation Coordinator — a forrás-node-on fut, küldi a prefetch-et
# ---------------------------------------------------------------------------

class DelegationCoordinator:
    """
    A forrás-node delegálás-koordinátora. Amikor egy feladatot delegálni
    akar, először küld egy PREFETCH kérést, majd egy kis várakozás után
    a tényleges feladatot.
    """

    def __init__(self, source_node: str, send_fn: Callable[[str, Any], Any]):
        self.source_node = source_node
        self._send_fn = send_fn  # (target_node, message) -> response
        self._pending_prefetches: Dict[str, PrefetchRequest] = {}
        self._lock = threading.RLock()

    def delegate_task(
        self,
        task_id: str,
        target_node: str,
        skills: List[SkillDescriptor],
        contexts: List[ContextDescriptor],
        prefetch_lead_time: float = 0.1,
    ) -> Dict[str, Any]:
        """
        Teljes delegálási folyamat:
        1. PREFETCH küldése a cél-node-nak
        2. Várakozás (prefetch_lead_time) — idő a háttérben betöltéshez
        3. Tényleges feladat küldése
        """
        # 1. PREFETCH
        request = PrefetchRequest(
            request_id=f"pf_{task_id}_{int(time.time()*1000)}",
            task_id=task_id,
            source_node=self.source_node,
            target_node=target_node,
            skills=skills,
            contexts=contexts,
        )

        with self._lock:
            self._pending_prefetches[request.request_id] = request

        logger.info(
            f"[{self.source_node}] Sending PREFETCH to {target_node} "
            f"for task={task_id}"
        )
        prefetch_msg = {
            "type": "PREFETCH",
            "payload": {
                "request_id": request.request_id,
                "task_id": request.task_id,
                "source_node": request.source_node,
                "target_node": request.target_node,
                "skills": [
                    {"skill_id": s.skill_id, "version": s.version, "source": s.source}
                    for s in request.skills
                ],
                "contexts": [
                    {
                        "context_id": c.context_id,
                        "context_type": c.context_type,
                        "size_hint": c.size_hint,
                    }
                    for c in request.contexts
                ],
                "ttl_seconds": request.ttl_seconds,
            }
        }
        pf_response = self._send_fn(target_node, prefetch_msg)

        # 2. Lead time — hagyjuk a prefetch-et fusson
        if prefetch_lead_time > 0:
            time.sleep(prefetch_lead_time)

        # 3. Tényleges feladat
        task_msg = {
            "type": "TASK",
            "payload": {
                "task_id": task_id,
                "source_node": self.source_node,
                "target_node": target_node,
                "prefetch_request_id": request.request_id,
                "skills": [s.key() for s in skills],
                "contexts": [c.key() for c in contexts],
                "instruction": "Execute delegated task with pre-loaded resources",
            }
        }
        logger.info(
            f"[{self.source_node}] Sending TASK to {target_node} "
            f"for task={task_id}"
        )
        task_response = self._send_fn(target_node, task_msg)

        return {
            "task_id": task_id,
            "target_node": target_node,
            "prefetch_request_id": request.request_id,
            "prefetch_response": pf_response,
            "task_response": task_response,
        }


# ---------------------------------------------------------------------------
# Simulated A2A Mesh Node — összeköti a koordinátort és a prefetch managert
# ---------------------------------------------------------------------------

class MeshNode:
    """
    Egy A2A Mesh node, ami egyszerre tud feladatot delegálni és fogadni.
    Szimulált hálózati kommunikációval (in-process message passing).
    """

    def __init__(self, node_id: str):
        self.node_id = node_id
        self.prefetch_manager = PrefetchManager(node_id)
        self.delegation_coordinator = DelegationCoordinator(
            source_node=node_id,
            send_fn=self._send_message,
        )
        self._peers: Dict[str, "MeshNode"] = {}
        self._task_results: Dict[str, Dict[str, Any]] = {}
        self._lock = threading.RLock()
        logger.info(f"MeshNode '{node_id}' initialized")

    def register_peer(self, peer: "MeshNode"):
        with self._lock:
            self._peers[peer.node_id] = peer

    def _send_message(self, target_node: str, message: Dict[str, Any]) -> Dict[str, Any]:
        """Szimulált hálózati küldés — in-process."""
        with self._lock:
            peer = self._peers.get(target_node)
        if peer is None:
            return {"error": f"Unknown peer: {target_node}"}
        return peer._receive_message(self.node_id, message)

    def _receive_message(
        self, source_node: str, message: Dict[str, Any]
    ) -> Dict[str, Any]:
        """Bejövő üzenet feldolgozása."""
        msg_type = message.get("type")
        payload = message.get("payload", {})

        if msg_type == "PREFETCH":
            # PREFETCH kérés feldolgozása
            skills = [
                SkillDescriptor(
                    skill_id=s["skill_id"],
                    version=s.get("version", "latest"),
                    source=s.get("source", "local"),
                )
                for s in payload.get("skills", [])
            ]
            contexts = [
                ContextDescriptor(
                    context_id=c["context_id"],
                    context_type=c.get("context_type", "generic"),
                    size_hint=c.get("size_hint", 0),
                )
                for c in payload.get("contexts", [])
            ]
            request = PrefetchRequest(
                request_id=payload["request_id"],
                task_id=payload["task_id"],
                source_node=payload["source_node"],
                target_node=payload["target_node"],
                skills=skills,
                contexts=contexts,
                ttl_seconds=payload.get("ttl_seconds", 30.0),
            )
            result = self.prefetch_manager.handle_prefetch(request)
            return {
                "status": "accepted",
                "state": result.state.value,
                "request_id": result.request_id,
            }

        elif msg_type == "TASK":
            # Tényleges feladat érkezése — ensure_ready
            task_id = payload["task_id"]
            skill_keys = payload.get("skills", [])
            context_keys = payload.get("contexts", [])

            # Rekonstruáljuk a descriptorokat (valós rendszerben a task-ban lenne)
            skills = [
                SkillDescriptor(skill_id=k.split("@")[0], version=k.split("@")[1] if "@" in k else "latest")
                for k in skill_keys
            ]
            contexts = [ContextDescriptor(context_id=k) for k in context_keys]

            result = self.prefetch_manager.ensure_ready(
                task_id=task_id,
                skills=skills,
                contexts=contexts,
                timeout=10.0,
            )

            response = {
                "task_id": task_id,
                "state": result.state.value,
                "loaded_skills": result.loaded_skills,
                "loaded_contexts": result.loaded_contexts,
                "duration_ms": result.duration_ms,
                "prefetch_hit": result.request_id != "direct",
            }
            if result.errors:
                response["errors"] = result.errors

            with self._lock:
                self._task_results[task_id] = response

            return response

        return {"error": f"Unknown message type: {msg_type}"}

    def delegate(
        self,
        task_id: str,
        target_node: str,
        skills: List[SkillDescriptor],
        contexts: List[ContextDescriptor],
        prefetch_lead_time: float = 0.1,
    ) -> Dict[str, Any]:
        return self.delegation_coordinator.delegate_task(
            task_id=task_id,
            target_node=target_node,
            skills=skills,
            contexts=contexts,
            prefetch_lead_time=prefetch_lead_time,
        )

    def get_stats(self) -> Dict[str, Any]:
        return {
            "node_id": self.node_id,
            "skill_registry": self.prefetch_manager.skill_registry.stats(),
            "context_cache": self.prefetch_manager.context_cache.stats(),
            "active_prefetches": len(self.prefetch_manager.list_prefetches()),
            "task_results": dict(self._task_results),
        }

    def shutdown(self):
        self.prefetch_manager.shutdown()


