def demo_prefetch_vs_direct():
    """
    Bemutató: összehasonlítja a prefetch-es delegálást a közvetlennel.
    A prefetch-es esetben a skill-ek és kontextusok már betöltve vannak,
    mire a feladat megérkezik, így az ensure_ready azonnal visszatér.
    """
    print("\n" + "=" * 70)
    print("A2A Mesh — Delegált feladatok pre-fetching demo")
    print("=" * 70)

    # Két node létrehozása
    node_a = MeshNode("node-alpha")
    node_b = MeshNode("node-beta")
    node_a.register_peer(node_b)
    node_b.register_peer(node_a)

    # Skill-ek és kontextusok, amik a feladathoz kellenek
    skills = [
        SkillDescriptor(skill_id="code-review", version="2.1", source="registry"),
        SkillDescriptor(skill_id="test-runner", version="1.5", source="local"),
        SkillDescriptor(skill_id="doc-generator", version="3.0", source="remote"),
    ]
    contexts = [
        ContextDescriptor(context_id="repo-snapshot-42", context_type="file", size_hint=50000),
        ContextDescriptor(context_id="ci-config-prod", context_type="file", size_hint=5000),
        ContextDescriptor(context_id="team-guidelines", context_type="url", size_hint=12000),
    ]

    # --- Eset 1: Prefetch-es delegálás ---
    print("\n--- Eset 1: Prefetch-es delegálás ---")
    t0 = time.time()
    result1 = node_a.delegate(
        task_id="task-001",
        target_node="node-beta",
        skills=skills,
        contexts=contexts,
        prefetch_lead_time=0.15,  # idő a háttérbetöltésnek
    )
    t1 = time.time()
    total1 = (t1 - t0) * 1000
    task_resp1 = result1["task_response"]
    print(f"  Összes delegálási idő: {total1:.1f}ms")
    print(f"  Task ensure_ready idő: {task_resp1.get('duration_ms', 0):.1f}ms")
    print(f"  Prefetch hit: {task_resp1.get('prefetch_hit')}")
    print(f"  State: {task_resp1.get('state')}")
    print(f"  Loaded skills: {task_resp1.get('loaded_skills')}")
    print(f"  Loaded contexts: {task_resp1.get('loaded_contexts')}")

    # --- Eset 2: Közvetlen delegálás (nincs prefetch) ---
    print("\n--- Eset 2: Közvetlen delegálás (nincs prefetch) ---")
    # Új skill-ek, amiket node-b még nem töltött be
    skills2 = [
        SkillDescriptor(skill_id="security-scan", version="1.0", source="registry"),
        SkillDescriptor(skill_id="lint-checker", version="2.2", source="local"),
    ]
    contexts2 = [
        ContextDescriptor(context_id="security-rules-v3", context_type="file", size_hint=8000),
        ContextDescriptor(context_id="lint-config-strict", context_type="file", size_hint=3000),
    ]

    t0 = time.time()
    # Szimuláljuk: közvetlen task küldés prefetch nélkül
    task_msg = {
        "type": "TASK",
        "payload": {
            "task_id": "task-002",
            "source_node": "node-alpha",
            "target_node": "node-beta",
            "prefetch_request_id": None,
            "skills": [s.key() for s in skills2],
            "contexts": [c.key() for c in contexts2],
        },
    }
    resp2 = node_a._send_message("node-beta", task_msg)
    t1 = time.time()
    total2 = (t1 - t0) * 1000
    print(f"  Összes delegálási idő: {total2:.1f}ms")
    print(f"  Task ensure_ready idő: {resp2.get('duration_ms', 0):.1f}ms")
    print(f"  Prefetch hit: {resp2.get('prefetch_hit')}")
    print(f"  State: {resp2.get('state')}")
    print(f"  Loaded skills: {resp2.get('loaded_skills')}")
    print(f"  Loaded contexts: {resp2.get('loaded_contexts')}")

    # --- Eset 3: Deduplikáció — ugyanazok a skill-ek újra ---
    print("\n--- Eset 3: Deduplikáció (ugyanazok a skill-ek újra) ---")
    result3 = node_a.delegate(
        task_id="task-003",
        target_node="node-beta",
        skills=skills,  # ugyanazok, mint task-001
        contexts=contexts,
        prefetch_lead_time=0.05,
    )
    task_resp3 = result3["task_response"]
    print(f"  Task ensure_ready idő: {task_resp3.get('duration_ms', 0):.1f}ms")
    print(f"  Prefetch hit: {task_resp3.get('prefetch_hit')}")
    print(f"  State: {task_resp3.get('state')}")

    # --- Statisztikák ---
    print("\n--- Node-beta statisztikák ---")
    stats = node_b.get_stats()
    print(f"  Cached skills: {stats['skill_registry']['cached_skills']}")
    print(f"  Cached contexts: {stats['context_cache']['cached_contexts']}")
    print(f"  Active prefetches: {stats['active_prefetches']}")
    print(f"  Skill load times: {json.dumps(stats['skill_registry']['load_times_ms'], indent=4)}")
    print(f"  Context load times: {json.dumps(stats['context_cache']['load_times_ms'], indent=4)}")

